   try{ pkgtype[i].value = document.getElementsByTagName("Kind_of_packages_code")[i].firstChild.data;}catch {}
   wc[i].value = document.getElementsByTagName("Gross_weight_itm")[i].firstChild.data; 
   wn[i].value = document.getElementsByTagName("Net_weight_itm")[i].firstChild.data;
  try{ unt[i].value = document.getElementsByTagName("Number_of_price_units")[i].firstChild.data; } catch{}
  try{
    unttype[i].value = document.getElementsByTagName("price_unit_code")[i].firstChild.data;
    bar[i].value = document.getElementsByTagName("barcode")[i].firstChild.data;
    com[i].value = document.getElementsByTagName("Free_text_1")[i].firstChild.data;
   }
   catch{
   bar[i].value="";
   com[i].value="";
   }
   try{ Pos000[i].value = document.getElementsByTagName("National_customs_procedure")[i].firstChild.data; } catch{}
  try{ Els[i].value = document.getElementsByTagName("Preference_code")[i].firstChild.data; } catch{ Els[i].value = "" ;}
