function FillNulls(){
var NUnt2 =document.getElementsByName('NUnt2');
var Unt2 = document.getElementsByName('Unt2');
var cnt ;
try{
cnt = document.getElementById('NumPkg').value*3;
}
catch {cnt=0;}
 //alert(cnt);
let j =0;
for(i=0; i<cnt; i++){
  let Nv = document.getElementsByTagName("Suppplementary_unit_quantity")[i].firstChild.data;
      Nv= Nv.replace(" ","").replace(/\r?\n|\r/g,"");
	  //alert("   "+Nv+"   "+i);
	   if (Nv.length != 0){
	   NUnt2[j].value=Nv;
	   Unt2[j].value = document.getElementsByTagName("Suppplementary_unit_code")[i].firstChild.data;
	   j=j+1;
	  }
}
}
