const SALT = "YEMEN_CUSTOMS_2024_SALT";
const SESSION_KEY = "bsh_session";
const SESSION_DURATION = 8 * 60 * 60 * 1000; // 8 ساعات
const MAX_ATTEMPTS = 5;
const LOCKOUT_DURATION = 15 * 60 * 1000; // 15 دقيقة

/* --- أدوات التشفير --- */
async function sha256(text) {
  const buf = await crypto.subtle.digest('SHA-256',
    new TextEncoder().encode(text));
  return Array.from(new Uint8Array(buf))
    .map(b => b.toString(16).padStart(2, '0')).join('');
}

/* --- إدارة محاولات الدخول (rate limiting) --- */
function getAttempts() {
  try {
    return JSON.parse(localStorage.getItem('bsh_attempts') || '{}');
  } catch { return {}; }
}

function saveAttempts(data) {
  localStorage.setItem('bsh_attempts', JSON.stringify(data));
}

function isLockedOut(index) {
  const attempts = getAttempts();
  const record = attempts[index];
  if (!record) return false;
  if (record.count >= MAX_ATTEMPTS) {
    const elapsed = Date.now() - record.lastAttempt;
    if (elapsed < LOCKOUT_DURATION) {
      const remaining = Math.ceil((LOCKOUT_DURATION - elapsed) / 60000);
      return remaining;
    }
    // انتهت فترة الحبس - صفر العداد
    delete attempts[index];
    saveAttempts(attempts);
    return false;
  }
  return false;
}

function recordFailedAttempt(index) {
  const attempts = getAttempts();
  if (!attempts[index]) attempts[index] = { count: 0, lastAttempt: 0 };
  attempts[index].count++;
  attempts[index].lastAttempt = Date.now();
  saveAttempts(attempts);
  return MAX_ATTEMPTS - attempts[index].count;
}

function resetAttempts(index) {
  const attempts = getAttempts();
  delete attempts[index];
  saveAttempts(attempts);
}

/* --- إدارة الجلسة (session) --- */
function setSession(index) {
  const session = {
    userIndex: index,
    token: crypto.getRandomValues(new Uint32Array(4)).join('-'),
    expiresAt: Date.now() + SESSION_DURATION,
    createdAt: Date.now()
  };
  // نخزن في sessionStorage (يُمسح عند إغلاق التبويب) - أكثر أماناً
  sessionStorage.setItem(SESSION_KEY, JSON.stringify(session));
}

function getValidSession() {
  try {
    const raw = sessionStorage.getItem(SESSION_KEY);
    if (!raw) return null;
    const session = JSON.parse(raw);
    if (Date.now() > session.expiresAt) {
      sessionStorage.removeItem(SESSION_KEY);
      return null;
    }
    return session;
  } catch { return null; }
}

function clearSession() {
  sessionStorage.removeItem(SESSION_KEY);
}

/* --- حماية ضد التجسس على DOM (اختياري) --- */
function sanitizeIndex(raw) {
  const idx = parseInt(String(raw).replace('bsh_', ''), 10);
  if (isNaN(idx) || idx < 1 || idx > PASSWORD_HASHES.length) return null;
  return idx;
}

/* ============================================================
   الدالة الرئيسية - ChkPass الآمنة
   ============================================================ */
async function ChkPass() {
  const errEl = document.getElementById("ErrPass");
  const userEl = document.getElementById("loginUser");
  const passEl = document.getElementById("loginPass");

  // إخفاء الخطأ السابق
  if (errEl) errEl.hidden = true;

  // 1) تحقق من اسم المستخدم
  const index = sanitizeIndex(userEl.value);
  if (index === null) {
    showError("رقم المستخدم غير صالح");
    return;
  }

  // 2) تحقق من الحبس
  const lockRemaining = isLockedOut(index);
  if (lockRemaining !== false) {
    showError(`تم قفل الحساب مؤقتاً. حاول بعد ${lockRemaining} دقيقة`);
    return;
  }

  // 3) التحقق من كلمة المرور
  const input = passEl.value;
  if (!input) {
    showError("أدخل كلمة المرور");
    return;
  }

  const inputHash = await sha256(input + SALT);
  const expectedHash = PASSWORD_HASHES[index - 1];

  // مقارنة بزمن ثابت (timing-safe) لمنع timing attacks
// alert(inputHash+'   '+ expectedHash);
 //if (timingSafeEqual(inputHash, expectedHash)) {
	 if (timingSafeEqual(inputHash, expectedHash)) {
    // ✅ نجاح
    resetAttempts(index);
    setSession(index);
    passEl.value = ''; // لا تُبقِ كلمة المرور في الذاكرة

    try {
      if (typeof AddTabl === 'function') AddTabl();
      document.getElementById("Btns").hidden = false;
      document.getElementById("MainDtl").hidden = false;
      document.getElementById("loginForm").hidden = true;
      document.getElementById("loginSection").hidden = true;
    } catch (e) {
      console.error("خطأ بعد الدخول:", e);
      showError("حدث خطأ في تهيئة النظام");
    }
  } 
  else {
    // ❌ فشل
    passEl.value = '';
    passEl.focus();
    const remaining = recordFailedAttempt(index);
    if (remaining <= 0) {
      showError("تم قفل الحساب لمدة 15 دقيقة بسبب المحاولات المتكررة");
    } else {
      showError(`كلمة المرور غير صحيحة. المحاولات المتبقية: ${remaining}`);
    }
  }
}

/* --- مقارنة بزمن ثابت --- */
function timingSafeEqual(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return diff === 0;
}

/* --- عرض الأخطاء --- */
function showError(msg) {
  const errEl = document.getElementById("ErrPass");
  if (errEl) {
    errEl.textContent = msg;
    errEl.hidden = false;
  }
}

